```go
package main

import (
    "errors"
    "fmt"
)

func parse() error { return errors.New("bad header") }

func importFile() error {
    if err := parse(); err != nil {
        return fmt.Errorf("import file: %w", err)
    }
    return nil
}

func main() { fmt.Println(importFile()) }
```
The output `import file: bad header` shows both layers, and the failure path is visible beside the parse call.

```go
package main

import (
    "errors"
    "fmt"
)

type writer struct{ err error }

func (w *writer) Write(text string) {
    if w.err != nil {
        return
    }
    if text == "bad" {
        w.err = errors.New("write failed")
    }
}

func main() {
    w := &writer{}
    w.Write("header")
    w.Write("bad")
    w.Write("footer")
    fmt.Println(w.err)
}
```
The value stores the first failure, skips dependent work, and reports `write failed` once at the operation boundary.

```go
package main

import (
    "errors"
    "fmt"
)

var ErrNotFound = errors.New("not found")
var errTimeout = errors.New("timeout")

type ConflictError struct{ Version int }

func (e *ConflictError) Error() string { return "version conflict" }
func IsRetryable(err error) bool       { return errors.Is(err, errTimeout) }

func main() {
    var conflict *ConflictError
    fmt.Println(errors.Is(ErrNotFound, ErrNotFound))
    fmt.Println(errors.As(error(&ConflictError{Version: 3}), &conflict), conflict.Version)
    fmt.Println(IsRetryable(fmt.Errorf("save: %w", errTimeout)))
}
```
The output demonstrates sentinel identity, typed detail `3`, and a package-owned retry classification as separate contracts.
